select 'IF NOT EXISTS(SELECT 1 FROM _tcomuserdefine WHERE '+'TableName	='+CONVERT(VARCHAR(30), ISNULL(TableName, 0))+' AND '+'DefineUnitSeq	='+CONVERT(VARCHAR(30), ISNULL(DefineUnitSeq, 0))+' AND '+'TitleSerl	='+CONVERT(VARCHAR(30), ISNULL(TitleSerl, 0))+' )'+CHAR(13)+'BEGIN '+CHAR(13)+-- INSERT SCRIPT FOR [_TCOMUserDefine]  'INSERT _TCOMUserDefine(CompanySeq, TableName, DefineUnitSeq, TitleSerl, Title, IsEss, CodeHelpConst, CodeHelpParams, SMInputType, MaskAndCaption, QrySort, IsFix, DataFieldID, IsCodeHelpTitle, LastUserSeq, LastDateTime, DecLen, WordSeq, Description) '+CHAR(13)+ + 'SELECT '+ CASE WHEN 'CompanySeq' IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, 'CompanySeq') END + ',' + CASE WHEN A.TableName IS NULL THEN N'NULL' ELSE 'dbo._FWDBAXmlUnescaped(N''' + dbo._FWDBAXmlEscaped(A.TableName) + ''')' END + ',' + CASE WHEN A.DefineUnitSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.DefineUnitSeq) END + ',' + CASE WHEN A.TitleSerl IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.TitleSerl) END + ',' + CASE WHEN A.Title IS NULL THEN N'NULL' ELSE 'dbo._FWDBAXmlUnescaped(N''' + dbo._FWDBAXmlEscaped(A.Title) + ''')' END + ',' + CASE WHEN A.IsEss IS NULL THEN N'NULL' ELSE 'dbo._FWDBAXmlUnescaped(N''' + dbo._FWDBAXmlEscaped(A.IsEss) + ''')' END + ',' + CASE WHEN A.CodeHelpConst IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.CodeHelpConst) END + ',' + CASE WHEN A.CodeHelpParams IS NULL THEN N'NULL' ELSE 'dbo._FWDBAXmlUnescaped(N''' + dbo._FWDBAXmlEscaped(A.CodeHelpParams) + ''')' END + ',' + CASE WHEN A.SMInputType IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.SMInputType) END + ',' + CASE WHEN A.MaskAndCaption IS NULL THEN N'NULL' ELSE 'dbo._FWDBAXmlUnescaped(N''' + dbo._FWDBAXmlEscaped(A.MaskAndCaption) + ''')' END + ',' + CASE WHEN A.QrySort IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.QrySort) END + ',' + CASE WHEN A.IsFix IS NULL THEN N'NULL' ELSE 'dbo._FWDBAXmlUnescaped(N''' + dbo._FWDBAXmlEscaped(A.IsFix) + ''')' END + ',' + CASE WHEN A.DataFieldID IS NULL THEN N'NULL' ELSE 'dbo._FWDBAXmlUnescaped(N''' + dbo._FWDBAXmlEscaped(A.DataFieldID) + ''')' END + ',' + CASE WHEN A.IsCodeHelpTitle IS NULL THEN N'NULL' ELSE 'dbo._FWDBAXmlUnescaped(N''' + dbo._FWDBAXmlEscaped(A.IsCodeHelpTitle) + ''')' END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN N'NULL' ELSE '''' + CONVERT(NVARCHAR, A.LastDateTime, 121) + '''' END + ',' + CASE WHEN A.DecLen IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.DecLen) END + ',' + CASE WHEN A.WordSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.WordSeq) END + ',' + CASE WHEN A.Description IS NULL THEN N'NULL' ELSE 'dbo._FWDBAXmlUnescaped(N''' + dbo._FWDBAXmlEscaped(A.Description) + ''')' END +' FROM _TCACOMPANY'+CHAR(13)+' end' FROM _TCOMUserDefine AS A WITH(NOLOCK)  where tablename = '_TDACust' and TitleSerl in (1000012,
1000013)




IF NOT EXISTS(SELECT 1 FROM _tcomuserdefine WHERE TableName	='_TDACust' AND DefineUnitSeq	=2004 AND TitleSerl	=1000012 )BEGIN INSERT _TCOMUserDefine(CompanySeq, TableName, DefineUnitSeq, TitleSerl, Title, IsEss, CodeHelpConst, CodeHelpParams, SMInputType, MaskAndCaption, QrySort, IsFix, DataFieldID, IsCodeHelpTitle, LastUserSeq, LastDateTime, DecLen, WordSeq, Description) SELECT CompanySeq,dbo._FWDBAXmlUnescaped(N'_TDACust'),2004,1000012,dbo._FWDBAXmlUnescaped(N'금액'),dbo._FWDBAXmlUnescaped(N'0'),0,dbo._FWDBAXmlUnescaped(N''),1027002,dbo._FWDBAXmlUnescaped(N''),15,dbo._FWDBAXmlUnescaped(N'0'),dbo._FWDBAXmlUnescaped(N''),dbo._FWDBAXmlUnescaped(N'0'),1,'2025-06-26 17:09:59.387',0,0,dbo._FWDBAXmlUnescaped(N'') FROM _TCACOMPANY end
